211	    /**
212	     * Known E.164 country codes whose national-number length is fixed, used to split the stored
213	     * telephone into its country code and national digits for display: Australia ({@code '61'}) and
214	     * the North American Numbering Plan ({@code '1'}). A number whose country code is not listed is
215	     * split by taking its leading digit as the (minimal) country code.
216	     */
217	    private static final Map<String, Integer> COUNTRY_NATIONAL_LENGTH = Map.of("61", 9, "1", 10);
218	
219	    /**
220	     * The stored E.164 {@link #getTelephone() telephone} formatted for humans: the country code, a
221	     * single space, then the national digits grouped in threes from the left (e.g. the stored
222	     * {@code '+61412345678'} becomes {@code '+61 412 345 678'}). The raw telephone itself stays in
223	     * E.164 form. Returns the stored value unchanged when it is absent or not a {@code '+'}-prefixed
224	     * digit string.
225	     *
226	     * @return the human-readable telephone, or the stored value when it cannot be formatted
227	     */
228	    public String getTelephoneDisplay() {
229	        if (this.telephone == null || !this.telephone.matches("\\+[0-9]+")) {
230	            return this.telephone;
231	        }
232	        String digits = this.telephone.substring(1);
233	        String countryCode = extractCountryCode(digits);
234	        String national = digits.substring(countryCode.length());
235	        StringBuilder display = new StringBuilder("+").append(countryCode);
236	        for (int i = 0; i < national.length(); i += 3) {
237	            display.append(' ').append(national, i, Math.min(i + 3, national.length()));
238	        }
239	        return display.toString();
240	    }
241	
242	    /**
243	     * Splits the country code off an E.164 digit string (country code followed by national digits,
244	     * without the leading {@code '+'}). A country code listed in {@link #COUNTRY_NATIONAL_LENGTH}
245	     * whose required national-number length matches the remaining digits is preferred; failing that,
246	     * the leading digit is used as the country code.
247	     *
248	     * @param digits the E.164 digits without the leading {@code '+'}
249	     * @return the country-code portion of {@code digits}
250	     */
251	    private static String extractCountryCode(String digits) {
252	        for (Map.Entry<String, Integer> entry : COUNTRY_NATIONAL_LENGTH.entrySet()) {
253	            String code = entry.getKey();
254	            if (digits.startsWith(code) && digits.length() - code.length() == entry.getValue()) {
255	                return code;
256	            }
257	        }
258	        return digits.substring(0, 1);
259	    }
