362	    /**
363	     * The owner's Luhn check digit, a single digit (0-9) computed over the digits contained in the
364	     * {@link #getCustomerCode() customer code}. Non-digit characters (such as the separators and the
365	     * letter prefixes) are ignored. Returns {@code null} when the customer code is absent.
366	     *
367	     * @return the Luhn check digit, or {@code null} when the customer code is absent
368	     */
369	    public Integer getCheckDigit() {
370	        if (this.customerCode == null) {
371	            return null;
372	        }
373	        int sum = 0;
374	        boolean dbl = true;
375	        for (int i = this.customerCode.length() - 1; i >= 0; i--) {
376	            char c = this.customerCode.charAt(i);
377	            if (c < '0' || c > '9') {
378	                continue;
379	            }
380	            int d = c - '0';
381	            if (dbl) {
382	                d *= 2;
383	                if (d > 9) {
384	                    d -= 9;
385	                }
386	            }
387	            sum += d;
388	            dbl = !dbl;
389	        }
390	        return (10 - (sum % 10)) % 10;
391	    }
