393	    /**
394	     * The owner's membership points, the score the {@link #getMembershipLevel() membership level} is
395	     * derived from. The score starts at 0 and gains: 2 when an email address is present, 1 when the
396	     * owner has no namesakes ({@code namesakeCount} is 0), 2 for a household of 3 or more members
397	     * ({@code householdSize} is at least 3), and 3 when the owner's tenure spans at least one elapsed
398	     * fiscal year (see {@link #getTenureFiscalYears()}). Because a newly created owner has zero
399	     * tenure, the tenure points are never awarded at create time.
400	     *
401	     * @return the membership points, a non-negative integer
402	     */
403	    public Integer getMembershipPoints() {
404	        int points = 0;
405	        boolean hasEmail = this.email != null && !this.email.isBlank();
406	        if (hasEmail) {
407	            points += 2;
408	        }
409	        boolean hasNoNamesakes = this.namesakeCount != null && this.namesakeCount == 0;
410	        if (hasNoNamesakes) {
411	            points += 1;
412	        }
413	        if (this.householdSize != null && this.householdSize >= 3) {
414	            points += 2;
415	        }
416	        Long tenureFiscalYears = getTenureFiscalYears();
417	        if (tenureFiscalYears != null && tenureFiscalYears >= 1) {
418	            points += 3;
419	        }
420	        return points;
421	    }
