512	    /**
513	     * The region the customer code's {@code <REGION>} component is built from: the postcode looked up
514	     * by range first (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099), falling back to the fixed
515	     * city-to-region table (Sydney->NSW, Melbourne->VIC, Brisbane->QLD) when the postcode is absent or
516	     * in no known range, and {@code 'UNKNOWN'} when neither resolves. Preferring the postcode returns
517	     * the same region for known cities but disambiguates cities that share a name.
518	     *
519	     * @return the canonical region string, or {@code 'UNKNOWN'}
520	     */
521	    private String deriveRegion() {
522	        String region = regionFromPostcode();
523	        if (region != null) {
524	            return region;
525	        }
526	        return CITY_REGION.getOrDefault(this.city, "UNKNOWN");
