529	    /**
530	     * Builds this owner's customer code, formatted {@code '<REGION>-<HASH8>'}. {@code REGION} is the
531	     * region derived from the postcode (falling back to the city, then {@code 'UNKNOWN'}; see
532	     * {@link #deriveRegion()}) and {@code HASH8} is the first 8 upper-case hexadecimal characters of
533	     * the SHA-256 digest of the owner's normalized telephone concatenated with its last name (e.g.
534	     * {@code 'NSW-1A2B3C4D'}). The code carries no sequence number, so it is a pure function of the
535	     * owner's region, telephone and last name. Call this once at create time and store the result via
536	     * {@link #setCustomerCode(String)}, which thereafter backs {@link #getLocality()},
537	     * {@link #getMembershipNumber()} and {@link #getCheckDigit()}.
538	     *
539	     * @return the assembled customer code
540	     */
541	    public String buildCustomerCode() {
542	        return deriveRegion() + "-" + sha256Hex8(this.telephone + this.getLastName());
543	    }
