545	    /**
546	     * Computes the first 8 upper-case hexadecimal characters (the first 4 bytes) of the SHA-256 digest
547	     * of the given value's UTF-8 bytes, the {@code HASH8} component of the customer code.
548	     *
549	     * @param value the value to hash
550	     * @return the 8-character upper-case hex prefix of the SHA-256 digest
551	     */
552	    private static String sha256Hex8(String value) {
553	        try {
554	            byte[] digest = MessageDigest.getInstance("SHA-256")
555	                .digest(value.getBytes(StandardCharsets.UTF_8));
556	            StringBuilder hex = new StringBuilder(8);
557	            for (int i = 0; i < 4; i++) {
558	                hex.append(String.format("%02X", digest[i]));
559	            }
560	            return hex.toString();
561	        }
562	        catch (NoSuchAlgorithmException e) {
563	            throw new IllegalStateException("SHA-256 algorithm not available", e);
564	        }
565	    }
