567	    /**
568	     * The region whose range contains this owner's postcode, or {@code null} when the postcode is
569	     * absent, not a 4-digit number, or in no known range.
570	     *
571	     * @return the matching region, or {@code null}
572	     */
573	    private String regionFromPostcode() {
574	        if (this.postcode == null) {
575	            return null;
576	        }
577	        int value;
578	        try {
579	            value = Integer.parseInt(this.postcode.trim());
580	        }
581	        catch (NumberFormatException ex) {
582	            return null;
583	        }
584	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE.entrySet()) {
585	            int[] range = entry.getValue();
586	            if (value >= range[0] && value <= range[1]) {
587	                return entry.getKey();
588	            }
589	        }
590	        return null;
591	    }
