604	    /**
605	     * The owner's identity key, the single derived value used for duplicate detection. It is the
606	     * lower-case SHA-256 hex digest (64 characters) of the owner's normalized telephone, lower-cased
607	     * email (empty when absent) and the {@linkplain Soundex#encode(String) Soundex} of its last name,
608	     * joined with {@code '|'} ({@code sha256hex('<telephone>|<lowerEmail>|<soundex(lastName)>')}); any
609	     * absent ({@code null}) component contributes an empty string before hashing. Two owners are
610	     * duplicates exactly when their whole identity keys are equal, so two owners sharing a last name
611	     * (and its Soundex) and postcode but carrying different telephones differ here and are both
612	     * allowed (the second is flagged a soft match rather than rejected).
613	     *
614	     * @return the derived identity key, a 64-character lower-case hex string
615	     */
616	    public String getIdentityKey() {
617	        String normalizedTelephone = this.telephone == null ? "" : this.telephone;
618	        String lowerEmail = this.email == null ? "" : this.email.toLowerCase(Locale.ROOT);
619	        String raw = normalizedTelephone + "|" + lowerEmail + "|" + Soundex.encode(this.getLastName());
620	        return sha256HexLower(raw);
621	    }
622	
623	    /**
624	     * The full lower-case SHA-256 hex digest (64 characters) of the given value's UTF-8 bytes, the
625	     * form the {@linkplain #getIdentityKey() identity key} takes.
626	     *
627	     * @param value the value to hash
628	     * @return the 64-character lower-case hex SHA-256 digest
629	     */
630	    private static String sha256HexLower(String value) {
631	        try {
632	            byte[] digest = MessageDigest.getInstance("SHA-256")
633	                .digest(value.getBytes(StandardCharsets.UTF_8));
634	            StringBuilder hex = new StringBuilder(digest.length * 2);
635	            for (byte b : digest) {
