733	    /**
734	     * Resolves the effective registration date and rolls it onto a business day. An absent
735	     * ({@code null}) value defaults to the server's current date; a supplied value is used as-is.
736	     * The resulting date is then rolled forward so it never falls on a weekend or a listed public
737	     * holiday: starting from the effective date, the date advances one day at a time while it lands
738	     * on a Saturday, a Sunday, or a date in {@link #PUBLIC_HOLIDAYS}, stopping on the first
739	     * non-holiday business day. A date already on a business day is returned unchanged.
740	     *
741	     * <p>This is the single definition of both the defaulting and the business-day roll, used
742	     * wherever the effective registration date is needed - by the {@code @PrePersist} hook that
743	     * stamps the owner and by the create endpoint that counts owners per business day.
744	     *
745	     * @param supplied the registration date from the request, or {@code null} when none was supplied
746	     * @return the effective registration date, guaranteed to fall on a non-holiday business day
747	     */
748	    public static LocalDate resolveRegistrationDate(LocalDate supplied) {
749	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
750	        while (!isBusinessDay(effective)) {
751	            effective = effective.plusDays(1);
752	        }
753	        return effective;
754	    }
