758	     */
759	    private static final Set<LocalDate> PUBLIC_HOLIDAYS = Set.of(
760	        LocalDate.of(2026, 1, 1),
761	        LocalDate.of(2026, 1, 26),
762	        LocalDate.of(2026, 4, 25),
763	        LocalDate.of(2026, 12, 25),
